export type Timer = { durationMs: number };
export function parseTimer(value: unknown): Timer {
 if (typeof value !== 'object' || value === null || !('durationMs' in value) || typeof value.durationMs !== 'number' || !Number.isFinite(value.durationMs) || value.durationMs < 0) throw new RangeError('Invalid timer');
 return { durationMs: value.durationMs };
}

